WITH band_category AS ( SELECT ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, i.i_category, SUM(cr.cr_return_amount) AS total_return_amount FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN household_demographics hd ON cr.cr_refunded_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, i.i_category ) SELECT ib_income_band_sk, ib_lower_bound, ib_upper_bound, i_category, total_return_amount, DENSE_RANK() OVER (ORDER BY total_return_amount DESC) AS band_category_rank, SUM(total_return_amount) OVER (ORDER BY total_return_amount DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_return_amount FROM band_category ORDER BY total_return_amount DESC
